def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 6 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < h and 0 <= ny < w and g[nx][ny] == 6 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append(cells)
    for cells in components:
        rows = [p[0] for p in cells]
        cols = [p[1] for p in cells]
        if len(cells) == 4 and max(rows)-min(rows) == 1 and max(cols)-min(cols) == 1:
            r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
            for r in range(r0-1, r1+2):
                for c in range(c0-1, c1+2):
                    if 0 <= r < h and 0 <= c < w and (r in (r0-1, r1+1) or c in (c0-1, c1+1)):
                        if not (r in (r0-1, r1+1) and c in (c0-1, c1+1)):
                            g[r][c] = 2
    return g
